// Studio's music library. Built-in tracks are generated by scripts/make-music.mjs from FFmpeg's tone
// generators (no third-party recordings, so no licence terms) and served from public/. A brand
// administrator can add tracks the company has licensed; those live in storage, listed in AppSetting.

export interface MusicTrack { id: string; title: string; note: string; builtIn: boolean; url: string }

export const BUILT_IN_MUSIC: MusicTrack[] = [
  { id: "calm", title: "Calm", note: "Soft chord pads", builtIn: true, url: "/studio/music/calm.m4a" },
  { id: "bright", title: "Bright", note: "Pads with a light, quick arpeggio", builtIn: true, url: "/studio/music/bright.m4a" },
  { id: "focus", title: "Focus", note: "Pads with a slow arpeggio", builtIn: true, url: "/studio/music/focus.m4a" },
];

/** An uploaded track as stored (the URL is built from its id). */
export interface StoredTrack { id: string; title: string; licence: string; storageKey: string; uploadedBy: string; uploadedAt: string }

export const uploadedTrackUrl = (id: string) => `/api/studio/music/${id}`;
